// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));

        address preOwner = c.owner();

        vm.prank(actor);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        address postOwner = c.owner();

        if (actor != preOwner) {
            assertTrue(postOwner == preOwner);
        } else {
            assertTrue(postOwner == preOwner || postOwner == newOwner);
        }
    }
}
